from .cli import main

if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

import sqlite3
import subprocess
import sys
from pathlib import Path

from evalmerge.pipeline import dump_results, ingest, report
from generate_fixtures import generate


def fetch_all(db_path: Path, sql: str) -> list[sqlite3.Row]:
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    try:
        return list(conn.execute(sql))
    finally:
        conn.close()


def warning_counts(db_path: Path) -> dict[str, int]:
    return {
        row["rule"]: row["count"]
        for row in fetch_all(
            db_path,
            "SELECT rule, COUNT(*) AS count FROM warnings GROUP BY rule ORDER BY rule",
        )
    }


def prepared(tmp_path: Path) -> tuple[Path, Path]:
    fixtures = tmp_path / "fixtures"
    db_path = tmp_path / "evalmerge.sqlite"
    generate(fixtures)
    ingest(fixtures, db_path)
    return fixtures, db_path


def test_ingests_all_formats_and_normalizes_rows(tmp_path: Path) -> None:
    _, db_path = prepared(tmp_path)
    rows = dump_results(db_path)

    by_source = {}
    for row in rows:
        by_source[row[1]] = by_source.get(row[1], 0) + 1
    assert by_source == {"a": 8, "b": 5, "c": 4}

    models = {row[2] for row in rows}
    assert "google/gemma-2-2b" in models
    assert "other-model" in models

    row_a001 = next(row for row in rows if row[0] == "a-001")
    assert row_a001[4] == 0.875
    assert row_a001[6] == "2026-05-01T12:00:00Z"

    row_a002 = next(row for row in rows if row[0] == "a-002")
    assert row_a002[4] == 0.72
    assert row_a002[6] == "2026-05-01T12:30:00Z"

    row_c001 = next(row for row in rows if row[0] == "c-001")
    assert row_c001[4] == 0.82
    assert row_c001[6] == "2026-05-03T00:00:00Z"


def test_planted_warning_counts_and_clamping(tmp_path: Path) -> None:
    _, db_path = prepared(tmp_path)
    assert warning_counts(db_path) == {
        "invalid_meta_json": 2,
        "missing_score": 2,
        "score_out_of_range": 2,
        "unknown_unit": 2,
        "unparseable_timestamp": 2,
    }

    clamped = {
        row["run_id"]: row["score"]
        for row in fetch_all(
            db_path,
            "SELECT run_id, score FROM results WHERE run_id IN ('a-003', 'a-007')",
        )
    }
    assert clamped == {"a-003": 1.0, "a-007": 0.0}

    extras = {
        row["run_id"]: row["raw_extra"]
        for row in fetch_all(
            db_path,
            "SELECT run_id, raw_extra FROM results WHERE run_id IN ('a-005', 'a-008', 'a-006', 'a-009')",
        )
    }
    assert extras["a-005"].startswith('{"meta":')
    assert extras["a-008"].startswith('{"meta":')
    assert extras["a-006"] == "[1,2]"
    assert extras["a-009"] == "[3,4]"


def test_format_b_later_file_corrections_win(tmp_path: Path) -> None:
    _, db_path = prepared(tmp_path)
    rows = {
        row["run_id"]: row
        for row in fetch_all(
            db_path,
            """
            SELECT run_id, score, stderr, ts_utc, raw_extra
            FROM results
            WHERE source = 'b'
            """,
        )
    }

    assert rows["b-dup-1"]["score"] == 0.66
    assert rows["b-dup-1"]["stderr"] == 0.025
    assert rows["b-dup-1"]["raw_extra"] == '{"tags":["corrected"]}'
    assert rows["b-dup-2"]["score"] == 0.80
    assert rows["b-002"]["ts_utc"] == "2026-05-01T13:00:00Z"

    stats = {
        row["key"]: row["value"]
        for row in fetch_all(db_path, "SELECT key, value FROM ingest_stats")
    }
    assert stats["duplicate_corrections"] == 2


def test_idempotent_result_dump(tmp_path: Path) -> None:
    fixtures, db_path = prepared(tmp_path)
    first = dump_results(db_path)
    first_warnings = warning_counts(db_path)

    ingest(fixtures, db_path)

    assert dump_results(db_path) == first
    assert warning_counts(db_path) == first_warnings
    stats = {
        row["key"]: row["value"]
        for row in fetch_all(db_path, "SELECT key, value FROM ingest_stats")
    }
    assert stats["duplicate_corrections"] == 2


def test_report_contains_exact_skip_counts_and_spellings(tmp_path: Path) -> None:
    _, db_path = prepared(tmp_path)
    text = report(db_path)

    assert "Rows ingested per source:\n  a: 8\n  b: 5\n  c: 4" in text
    assert "Rows skipped per rule:\n  missing_score: 2\n  unparseable_timestamp: 2" in text
    assert "Duplicate corrections applied: 2" in text
    assert "google/gemma-2-2b:" in text
    assert "Gemma-2 2B" in text
    assert "gemma-2-2b" in text


def test_cli_ingest_and_report(tmp_path: Path) -> None:
    fixtures = tmp_path / "fixtures"
    db_path = tmp_path / "evalmerge.sqlite"
    generate(fixtures)

    subprocess.run(
        [sys.executable, "-m", "evalmerge", "--db", str(db_path), "ingest", str(fixtures)],
        check=True,
        text=True,
    )
    result = subprocess.run(
        [sys.executable, "-m", "evalmerge", "--db", str(db_path), "report"],
        check=True,
        text=True,
        stdout=subprocess.PIPE,
    )
    assert "evalmerge data-quality report" in result.stdout
    assert "Duplicate corrections applied: 2" in result.stdout

from __future__ import annotations

import csv
import json
import re
import sqlite3
import xml.etree.ElementTree as ET
from collections import Counter, defaultdict
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from statistics import median
from typing import Any, Iterable

DEFAULT_DB = "evalmerge.sqlite"

SKIP_MISSING_SCORE = "missing_score"
SKIP_UNPARSEABLE_TIMESTAMP = "unparseable_timestamp"
WARN_INVALID_META_JSON = "invalid_meta_json"
WARN_SCORE_OUT_OF_RANGE = "score_out_of_range"
WARN_UNKNOWN_UNIT = "unknown_unit"


@dataclass(frozen=True)
class NormalizedRow:
    run_id: str
    source: str
    model: str
    task: str
    score: float
    stderr: float | None
    ts_utc: str
    raw_extra: str
    raw_model: str


@dataclass
class IngestState:
    warnings: Counter[str]
    duplicate_corrections: int = 0
    conn: sqlite3.Connection | None = None
    seen_keys: set[tuple[str, str]] | None = None


def connect(db_path: Path) -> sqlite3.Connection:
    conn = sqlite3.connect(db_path)
    conn.execute("PRAGMA foreign_keys = ON")
    conn.execute("PRAGMA journal_mode = DELETE")
    conn.execute("PRAGMA synchronous = FULL")
    conn.row_factory = sqlite3.Row
    init_db(conn)
    return conn


def init_db(conn: sqlite3.Connection) -> None:
    conn.executescript(
        """
        CREATE TABLE IF NOT EXISTS results (
            run_id TEXT NOT NULL,
            source TEXT NOT NULL CHECK (source IN ('a', 'b', 'c')),
            model TEXT NOT NULL,
            task TEXT NOT NULL,
            score REAL NOT NULL,
            stderr REAL NULL,
            ts_utc TEXT NOT NULL,
            raw_extra TEXT NOT NULL,
            UNIQUE(run_id, source)
        );

        CREATE TABLE IF NOT EXISTS warnings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            rule TEXT NOT NULL,
            source TEXT NOT NULL,
            file TEXT NOT NULL,
            row_ref TEXT NOT NULL,
            message TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS model_spellings (
            normalized TEXT NOT NULL,
            raw TEXT NOT NULL,
            PRIMARY KEY (normalized, raw)
        );

        CREATE TABLE IF NOT EXISTS ingest_stats (
            key TEXT PRIMARY KEY,
            value INTEGER NOT NULL
        );
        """
    )


def ingest(input_dir: Path, db_path: Path = Path(DEFAULT_DB)) -> None:
    input_dir = input_dir.resolve()
    conn = connect(db_path)
    state = IngestState(Counter(), conn=conn, seen_keys=set())
    try:
        with conn:
            conn.execute("DELETE FROM warnings")
            conn.execute("DELETE FROM model_spellings")
            conn.execute("DELETE FROM ingest_stats")

        for row in discover_rows(input_dir, state):
            upsert_result(conn, row, state)

        with conn:
            skip_rules = {SKIP_MISSING_SCORE, SKIP_UNPARSEABLE_TIMESTAMP}
            for rule, count in sorted(state.warnings.items()):
                conn.execute(
                    "INSERT INTO ingest_stats(key, value) VALUES(?, ?)",
                    (f"warning:{rule}", count),
                )
                if rule not in skip_rules:
                    continue
                conn.execute(
                    "INSERT INTO ingest_stats(key, value) VALUES(?, ?)",
                    (f"skipped:{rule}", count),
                )
            conn.execute(
                "INSERT INTO ingest_stats(key, value) VALUES(?, ?)",
                ("duplicate_corrections", state.duplicate_corrections),
            )
    finally:
        conn.close()


def discover_rows(input_dir: Path, state: IngestState) -> Iterable[NormalizedRow]:
    harness_a = input_dir / "harness_a"
    if harness_a.exists():
        for path in sorted(harness_a.glob("*.csv")):
            yield from parse_a(path, state)

    harness_b = input_dir / "harness_b"
    if harness_b.exists():
        for path in sorted(harness_b.glob("*.jsonl")):
            yield from parse_b(path, state)

    path_c = input_dir / "harness_c" / "results.xml"
    if path_c.exists():
        yield from parse_c(path_c, state)


def parse_a(path: Path, state: IngestState) -> Iterable[NormalizedRow]:
    with path.open("r", encoding="utf-8-sig", newline="") as fh:
        reader = csv.reader(fh)
        header = next(reader, None)
        if not header:
            return
        for line_no, row in enumerate(reader, start=2):
            if not row or all(not field.strip() for field in row):
                continue
            if len(row) < 6:
                warn(state, SKIP_MISSING_SCORE, "a", path, str(line_no), "row has too few columns")
                continue
            run_id, raw_model, task, score_raw, ts_raw = [part.strip() for part in row[:5]]
            meta_raw = ",".join(row[5:]).strip()
            score = parse_score(score_raw, None, state, "a", path, str(line_no))
            if score is None:
                continue
            ts_utc = parse_timestamp(ts_raw)
            if ts_utc is None:
                warn(
                    state,
                    SKIP_UNPARSEABLE_TIMESTAMP,
                    "a",
                    path,
                    str(line_no),
                    f"could not parse timestamp {ts_raw!r}",
                )
                continue
            raw_extra = parse_meta(meta_raw, state, "a", path, str(line_no))
            yield NormalizedRow(
                run_id=run_id,
                source="a",
                model=normalize_model(raw_model),
                task=task,
                score=score,
                stderr=None,
                ts_utc=ts_utc,
                raw_extra=raw_extra,
                raw_model=raw_model,
            )


def parse_b(path: Path, state: IngestState) -> Iterable[NormalizedRow]:
    with path.open("r", encoding="utf-8") as fh:
        for line_no, line in enumerate(fh, start=1):
            stripped = line.strip()
            if not stripped or stripped == "null":
                continue
            try:
                obj = json.loads(stripped)
            except json.JSONDecodeError:
                warn(state, SKIP_MISSING_SCORE, "b", path, str(line_no), "invalid json line")
                continue
            if obj is None:
                continue
            metrics = obj.get("metrics") or {}
            score = parse_score(metrics.get("acc"), None, state, "b", path, str(line_no))
            if score is None:
                continue
            ts_utc = parse_epoch(obj.get("ts"))
            if ts_utc is None:
                warn(
                    state,
                    SKIP_UNPARSEABLE_TIMESTAMP,
                    "b",
                    path,
                    str(line_no),
                    f"could not parse epoch {obj.get('ts')!r}",
                )
                continue
            raw_model = str(obj.get("model_name", "")).strip()
            extra = {"tags": obj.get("tags", [])}
            yield NormalizedRow(
                run_id=str(obj.get("id", "")).strip(),
                source="b",
                model=normalize_model(raw_model),
                task=str(obj.get("benchmark", "")).strip(),
                score=score,
                stderr=optional_float(metrics.get("stderr")),
                ts_utc=ts_utc,
                raw_extra=stable_json(extra),
                raw_model=raw_model,
            )


def parse_c(path: Path, state: IngestState) -> Iterable[NormalizedRow]:
    tree = ET.parse(path)
    root = tree.getroot()
    for index, run in enumerate(root.findall("run"), start=1):
        run_id = (run.get("id") or "").strip()
        raw_model = text_of(run, "model")
        task = text_of(run, "task")
        score_el = run.find("score")
        if score_el is None or score_el.text is None or not score_el.text.strip():
            warn(state, SKIP_MISSING_SCORE, "c", path, run_id or str(index), "missing score")
            continue
        unit = (score_el.get("unit") or "fraction").strip().lower()
        score = parse_score(score_el.text.strip(), unit, state, "c", path, run_id or str(index))
        if score is None:
            continue
        date_raw = text_of(run, "date")
        ts_utc = parse_date(date_raw)
        if ts_utc is None:
            warn(
                state,
                SKIP_UNPARSEABLE_TIMESTAMP,
                "c",
                path,
                run_id or str(index),
                f"could not parse date {date_raw!r}",
            )
            continue
        yield NormalizedRow(
            run_id=run_id,
            source="c",
            model=normalize_model(raw_model),
            task=task,
            score=score,
            stderr=None,
            ts_utc=ts_utc,
            raw_extra=stable_json({"unit": unit}),
            raw_model=raw_model,
        )


def parse_score(
    value: Any,
    unit: str | None,
    state: IngestState,
    source: str,
    path: Path,
    row_ref: str,
) -> float | None:
    if value is None or str(value).strip() == "":
        warn(state, SKIP_MISSING_SCORE, source, path, row_ref, "missing score")
        return None
    raw = str(value).strip()
    try:
        if raw.endswith("%"):
            score = float(raw[:-1]) / 100.0
        elif unit == "percent":
            score = float(raw) / 100.0
        elif unit == "fraction" or unit is None:
            score = float(raw)
        else:
            numeric = float(raw)
            warn(
                state,
                WARN_UNKNOWN_UNIT,
                source,
                path,
                row_ref,
                f"unknown score unit {unit!r}",
            )
            score = numeric / 100.0 if numeric > 1 else numeric
    except ValueError:
        warn(state, SKIP_MISSING_SCORE, source, path, row_ref, f"invalid score {raw!r}")
        return None

    if score < 0.0 or score > 1.0:
        warn(
            state,
            WARN_SCORE_OUT_OF_RANGE,
            source,
            path,
            row_ref,
            f"score {score!r} outside [0, 1]",
        )
        score = max(0.0, min(1.0, score))
    return score


def parse_timestamp(raw: str) -> str | None:
    raw = raw.strip()
    formats = ("%Y-%m-%dT%H:%M:%SZ", "%m/%d/%Y %H:%M")
    for fmt in formats:
        try:
            return rfc3339(datetime.strptime(raw, fmt).replace(tzinfo=timezone.utc))
        except ValueError:
            pass
    return None


def parse_epoch(value: Any) -> str | None:
    try:
        epoch = float(value)
    except (TypeError, ValueError):
        return None
    if epoch > 10_000_000_000:
        epoch /= 1000.0
    try:
        return rfc3339(datetime.fromtimestamp(epoch, tz=timezone.utc))
    except (OverflowError, OSError, ValueError):
        return None


def parse_date(raw: str) -> str | None:
    try:
        dt = datetime.strptime(raw.strip(), "%Y-%m-%d").replace(tzinfo=timezone.utc)
    except ValueError:
        return None
    return rfc3339(dt)


def parse_meta(raw: str, state: IngestState, source: str, path: Path, row_ref: str) -> str:
    if not raw:
        return stable_json({})
    try:
        return stable_json(json.loads(raw))
    except json.JSONDecodeError:
        warn(state, WARN_INVALID_META_JSON, source, path, row_ref, "invalid meta json")
        return stable_json({"meta": raw})


def normalize_model(raw: str) -> str:
    value = raw.strip().lower()
    value = re.sub(r"[^a-z0-9]+", "-", value)
    value = re.sub(r"-+", "-", value).strip("-")
    aliases = {
        "gemma-2-2b": "google/gemma-2-2b",
        "google-gemma-2-2b": "google/gemma-2-2b",
    }
    return aliases.get(value, value)


def text_of(parent: ET.Element, child: str) -> str:
    node = parent.find(child)
    return "" if node is None or node.text is None else node.text.strip()


def stable_json(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"))


def optional_float(value: Any) -> float | None:
    try:
        return None if value is None else float(value)
    except (TypeError, ValueError):
        return None


def rfc3339(dt: datetime) -> str:
    return dt.astimezone(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def warn(
    state: IngestState,
    rule: str,
    source: str,
    path: Path,
    row_ref: str,
    message: str,
) -> None:
    state.warnings[rule] += 1
    conn = state.conn
    if conn is not None:
        conn.execute(
            "INSERT INTO warnings(rule, source, file, row_ref, message) VALUES (?, ?, ?, ?, ?)",
            (rule, source, str(path), row_ref, message),
        )


def upsert_result(conn: sqlite3.Connection, row: NormalizedRow, state: IngestState) -> None:
    with conn:
        key = (row.run_id, row.source)
        if row.source == "b" and state.seen_keys is not None and key in state.seen_keys:
            state.duplicate_corrections += 1
        if state.seen_keys is not None:
            state.seen_keys.add(key)
        conn.execute(
            """
            INSERT INTO results(run_id, source, model, task, score, stderr, ts_utc, raw_extra)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(run_id, source) DO UPDATE SET
                model = excluded.model,
                task = excluded.task,
                score = excluded.score,
                stderr = excluded.stderr,
                ts_utc = excluded.ts_utc,
                raw_extra = excluded.raw_extra
            """,
            (
                row.run_id,
                row.source,
                row.model,
                row.task,
                row.score,
                row.stderr,
                row.ts_utc,
                row.raw_extra,
            ),
        )
        conn.execute(
            "INSERT OR IGNORE INTO model_spellings(normalized, raw) VALUES (?, ?)",
            (row.model, row.raw_model),
        )


def report(db_path: Path = Path(DEFAULT_DB)) -> str:
    conn = connect(db_path)
    try:
        rows_by_source = {
            row["source"]: row["count"]
            for row in conn.execute(
                "SELECT source, COUNT(*) AS count FROM results GROUP BY source ORDER BY source"
            )
        }
        skip_counts = {
            row["rule"].replace("skipped:", ""): row["value"]
            for row in conn.execute(
                "SELECT key AS rule, value FROM ingest_stats WHERE key LIKE 'skipped:%' ORDER BY key"
            )
        }
        duplicate_corrections = conn.execute(
            "SELECT value FROM ingest_stats WHERE key = 'duplicate_corrections'"
        ).fetchone()
        correction_count = duplicate_corrections["value"] if duplicate_corrections else 0

        scores: dict[str, list[float]] = defaultdict(list)
        for row in conn.execute("SELECT model, score FROM results ORDER BY model, score"):
            scores[row["model"]].append(float(row["score"]))

        spellings = [
            (row["normalized"], row["raws"])
            for row in conn.execute(
                """
                SELECT normalized, GROUP_CONCAT(raw, ' | ') AS raws, COUNT(*) AS count
                FROM (
                    SELECT normalized, raw FROM model_spellings ORDER BY normalized, raw
                )
                GROUP BY normalized
                HAVING count >= 2
                ORDER BY normalized
                """
            )
        ]

        lines = ["evalmerge data-quality report", ""]
        lines.append("Rows ingested per source:")
        for source in ("a", "b", "c"):
            lines.append(f"  {source}: {rows_by_source.get(source, 0)}")
        lines.append("")
        lines.append("Rows skipped per rule:")
        for rule in (SKIP_MISSING_SCORE, SKIP_UNPARSEABLE_TIMESTAMP):
            lines.append(f"  {rule}: {skip_counts.get(rule, 0)}")
        lines.append("")
        lines.append(f"Duplicate corrections applied: {correction_count}")
        lines.append("")
        lines.append("Score distribution by model:")
        for model in sorted(scores):
            values = scores[model]
            lines.append(
                f"  {model}: min={min(values):.4f} median={median(values):.4f} max={max(values):.4f}"
            )
        lines.append("")
        lines.append("Models with multiple raw spellings:")
        if spellings:
            for normalized, raws in spellings:
                lines.append(f"  {normalized}: {raws}")
        else:
            lines.append("  none")
        return "\n".join(lines) + "\n"
    finally:
        conn.close()


def dump_results(db_path: Path) -> list[tuple[Any, ...]]:
    conn = connect(db_path)
    try:
        return [
            tuple(row)
            for row in conn.execute(
                """
                SELECT run_id, source, model, task, score, stderr, ts_utc, raw_extra
                FROM results
                ORDER BY source, run_id
                """
            )
        ]
    finally:
        conn.close()
